export default [{"id":"2484","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ","aya_text_emlaey":"اقترب للناس حسابهم وهم في غفلة معرضون","aya_tafseer":"[1] دنا وقت حساب الناس على ما قدَّموا من عمل، ومع ذلك فالكفار يعيشون لاهين عن هذه الحقيقة، معرضين عن هذا الإنذار."},{"id":"2485","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"2","aya_text":"مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ","aya_text_emlaey":"ما يأتيهم من ذكر من ربهم محدث إلا استمعوه وهم يلعبون","aya_tafseer":"[2] ما من شيء ينزل من القرآن يتلى عليهم مجدِّداً لهم التذكير، إلا كان سماعهم له سماع لعب واستهزاء."},{"id":"2486","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"7","aya_no":"3","aya_text":"لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ","aya_text_emlaey":"لاهية قلوبهم وأسروا النجوى الذين ظلموا هل هذا إلا بشر مثلكم أفتأتون السحر وأنتم تبصرون","aya_tafseer":"[3] قلوبهم غافلة عن القرآن الكريم، مشغولة بأباطيل الدنيا وشهواتها، لا يعقلون ما فيه. بل إن الظالمين من قريش اجتمعوا سرّاً على أمر خَفِيٍّ: وهو إشاعة ما يصدُّون به الناس عن الإيمان بمحمد -صلى الله عليه وسلم- من أنه بشر مثلهم، لا يختلف عنهم في شيء، وأن ما جاء به من القرآن سحر، فكيف تجيئون إليه وتتبعونه، وأنتم تبصرون أنه بشر مثلكم؟"},{"id":"2487","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"4","aya_text":"قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"قال ربي يعلم القول في السماء والأرض وهو السميع العليم","aya_tafseer":"[4] ردَّ النبيُّ -صلى الله عليه وسلم- الأمرَ إلى ربه سبحانه وتعالى فقال: ربي يعلم القول في السماء والأرض، ويعلم ما أسررتموه من حديثكم، وهو السميع لأقوالكم، العليم بأحوالكم. وفي هذا تهديد لهم ووعيد."},{"id":"2488","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"9","aya_no":"5","aya_text":"بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ","aya_text_emlaey":"بل قالوا أضغاث أحلام بل افتراه بل هو شاعر فليأتنا بآية كما أرسل الأولون","aya_tafseer":"[5] بل جحد الكفار القرآن فمِن قائل: إنه أخلاط أحلام لا حقيقة لها، ومن قائل: إنه اختلاق وكذب وليس وحياً، ومن قائل: إن محمداً شاعر، وهذا الذي جاء به شعر، وإن أراد منا أن نصدِّقه فليجئنا بمعجزة محسوسة كناقة صالح، وآيات موسى وعيسى، وما جاء به الرسل من قبله."},{"id":"2489","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"10","aya_no":"6","aya_text":"مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ","aya_text_emlaey":"ما آمنت قبلهم من قرية أهلكناها أفهم يؤمنون","aya_tafseer":"[6] ما آمنت قبل كفار «مكة» من قرية طلب أهلها المعجزات مِن رسولهم وتحققت، بل كذَّبوا، فأهلكناهم، أفيؤمن كفار «مكة» إذا تحققت المعجزات التي طلبوها؟ كَلَّا إنهم لا يؤمنون."},{"id":"2490","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"7","aya_text":"وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"وما أرسلنا قبلك إلا رجالا نوحي إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون","aya_tafseer":"[7] وما أرسلنا قبلك -أيها الرسول- إلا رجالاً من البشر نوحي إليهم، ولم نرسل ملائكة، فاسألوا -يا كفار «مكة»- أهل العلم بالكتب المنزلة السابقة، إن كنتم تجهلون ذلك."},{"id":"2491","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"8","aya_text":"وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ","aya_text_emlaey":"وما جعلناهم جسدا لا يأكلون الطعام وما كانوا خالدين","aya_tafseer":"[8] وما جعلنا أولئك المرسلين قبلك خارجين عن طباع البشر لا يحتاجون إلى طعام وشراب، وما كانوا خالدين لا يموتون."},{"id":"2492","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"9","aya_text":"ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ","aya_text_emlaey":"ثم صدقناهم الوعد فأنجيناهم ومن نشاء وأهلكنا المسرفين","aya_tafseer":"[9] ثم أنجزنا للأنبياء وأتباعهم ما وعدناهم به من النصر والنجاة، وأهلَكْنا المسرفين على أنفسهم بكفرهم بربهم."},{"id":"2493","jozz":"17","page":"322","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"15","line_end":"15","aya_no":"10","aya_text":"لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"لقد أنـزلنا إليكم كتابا فيه ذكركم أفلا تعقلون","aya_tafseer":"[10] لقد أنزلنا إليكم هذا القرآن، فيه عزُّكم وشرفكم في الدنيا والآخرة إن تذكرتم به، أفلا تعقلون ما فَضَّلْتكم به على غيركم؟"},{"id":"2494","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"11","aya_text":"وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ","aya_text_emlaey":"وكم قصمنا من قرية كانت ظالمة وأنشأنا بعدها قوما آخرين","aya_tafseer":"[11] وكثير من القرى كان أهلها ظالمين بكفرهم بما جاءتهم به رسلهم، فأهلكناهم بعذاب أبادهم جميعاً، وأوجدنا بعدهم قوماً آخرين سواهم."},{"id":"2495","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"2","aya_no":"12","aya_text":"فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ","aya_text_emlaey":"فلما أحسوا بأسنا إذا هم منها يركضون","aya_tafseer":"[12] فلما رأى هؤلاء الظالمون عذابنا الشديد نازلاً بهم، وشاهدوا بوادره، إذا هم من قريتهم يسرعون هاربين."},{"id":"2496","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"4","aya_no":"13","aya_text":"لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ","aya_text_emlaey":"لا تركضوا وارجعوا إلى ما أترفتم فيه ومساكنكم لعلكم تسألون","aya_tafseer":"[13] فنودوا في هذه الحال: لا تهربوا وارجعوا إلى لذاتكم وتنعُّمكم في دنياكم الملهية ومساكنكم المشيَّدة، لعلكم تُسألون من دنياكم شيئاً، وذلك على وجه السخرية والاستهزاء بهم."},{"id":"2497","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"4","aya_no":"14","aya_text":"قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ","aya_text_emlaey":"قالوا ياويلنا إنا كنا ظالمين","aya_tafseer":"[14] فلم يكن لهم من جواب إلا اعترافهم بجرمهم وقولهم: يا هلاكنا، فقد ظلمنا أنفسنا بكفرنا."},{"id":"2498","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"15","aya_text":"فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ","aya_text_emlaey":"فما زالت تلك دعواهم حتى جعلناهم حصيدا خامدين","aya_tafseer":"[15] فما زالت تلك المقالة -وهي الدعاء على أنفسهم بالهلاك، والاعتراف بالظلم- دَعْوَتَهم يرددونها حتى جعلناهم كالزرع المحصود، خامدين لا حياة فيهم. فاحذروا -أيها المخاطبون- أن تستمروا على تكذيب محمد -صلى الله عليه وسلم-، فيحلُّ بكم ما حَلَّ بالأمم قبلكم."},{"id":"2499","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"6","aya_no":"16","aya_text":"وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ","aya_text_emlaey":"وما خلقنا السماء والأرض وما بينهما لاعبين","aya_tafseer":"[16] وما خلقنا السماء والأرض وما بينهما عبثاً وباطلاً، بل لإقامة الحجة عليكم -أيها الناس- ولتعتبروا بذلك كله، فتعلموا أن الذي خلق ذلك لا يشبهه شيء، ولا تصلح العبادة إلا له."},{"id":"2500","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"17","aya_text":"لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ","aya_text_emlaey":"لو أردنا أن نتخذ لهوا لاتخذناه من لدنا إن كنا فاعلين","aya_tafseer":"[17] لو أردنا أن نتخذ لهواً من الولد أو الصاحبة لاتخذناه مِن عندنا لا من عندكم، ما كنا فاعلين ذلك؛ لاستحالة أن يكون لنا ولد أو صاحبة."},{"id":"2501","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"18","aya_text":"بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ","aya_text_emlaey":"بل نقذف بالحق على الباطل فيدمغه فإذا هو زاهق ولكم الويل مما تصفون","aya_tafseer":"[18] بل نقذف بالحق ونبيِّنه، فيدحض الباطل، فإذا هو ذاهب مضمحل. ولكم العذاب في الآخرة -أيها المشركون- مِن وَصْفكم ربكم بغير صفته اللائقة به."},{"id":"2502","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"10","aya_no":"19","aya_text":"وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ","aya_text_emlaey":"وله من في السموات والأرض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون","aya_tafseer":"[19] ولله سبحانه كل مَن في السموات والأرض، والذين عنده من الملائكة لا يأنَفُون عن عبادته ولا يملُّونها. فكيف يجوز أن يشرك به ما هو عبده وخلقه؟"},{"id":"2503","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"11","aya_no":"20","aya_text":"يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ","aya_text_emlaey":"يسبحون الليل والنهار لا يفترون","aya_tafseer":"[20] يذكرون الله وينزِّهونه دائماً، لا يَضْعُفون ولا يسأمون."},{"id":"2504","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"11","aya_no":"21","aya_text":"أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ","aya_text_emlaey":"أم اتخذوا آلهة من الأرض هم ينشرون","aya_tafseer":"[21] كيف يصح للمشركين أن يتخذوا آلهة عاجزة من الأرض لا تقدر على إحياء الموتى؟"},{"id":"2505","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"22","aya_text":"لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ","aya_text_emlaey":"لو كان فيهما آلهة إلا الله لفسدتا فسبحان الله رب العرش عما يصفون","aya_tafseer":"[22] لو كان في السموات والأرض آلهة غير الله سبحانه وتعالى تدبِّر شؤونهما، لاختلَّ نظامهما، فتنزَّه الله رب العرش، وتقدَّس عَمَّا يصفه الجاحدون الكافرون، من الكذب والافتراء وكل نقص."},{"id":"2506","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"13","aya_no":"23","aya_text":"لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ","aya_text_emlaey":"لا يسأل عما يفعل وهم يسألون","aya_tafseer":"[23] إن من دلائل تفرُّده سبحانه بالخلق والعبادة أنه لا يُسأل عن قضائه في خلقه، وجميع خلقه يُسألون عن أفعالهم."},{"id":"2507","jozz":"17","page":"323","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"15","aya_no":"24","aya_text":"أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ","aya_text_emlaey":"أم اتخذوا من دونه آلهة قل هاتوا برهانكم هذا ذكر من معي وذكر من قبلي بل أكثرهم لا يعلمون الحق فهم معرضون","aya_tafseer":"[24] هل اتخذ هؤلاء المشركون مِن غير الله آلهة تنفع وتضر وتحيي وتميت؟ قل -أيها الرسول- لهم: هاتوا ما لديكم من البرهان على ما اتخذتموه آلهة، فليس في القرآن الذي جئتُ به ولا في الكتب السابقة دليل على ما ذهبتم إليه، وما أشركوا إلا جهلاً وتقليداً، فهم معرضون عن الحق منكرون له."},{"id":"2508","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"25","aya_text":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ","aya_text_emlaey":"وما أرسلنا من قبلك من رسول إلا نوحي إليه أنه لا إله إلا أنا فاعبدون","aya_tafseer":"[25] وما أرسلنا من قبلك -أيها الرسول- من رسول إلا نوحي إليه أنه لا معبود بحق إلا الله، فأخْلِصوا العبادة له وحده."},{"id":"2509","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"3","aya_no":"26","aya_text":"وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ","aya_text_emlaey":"وقالوا اتخذ الرحمن ولدا سبحانه بل عباد مكرمون","aya_tafseer":"[26] وقال المشركون: اتخذ الرحمن ولداً بزعمهم أن الملائكة بنات الله. تنزَّه الله عن ذلك؛ فالملائكة عباد الله مقرَّبون مخصوصون بالفضائل،"},{"id":"2510","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"4","aya_no":"27","aya_text":"لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ","aya_text_emlaey":"لا يسبقونه بالقول وهم بأمره يعملون","aya_tafseer":"[27] وهم في حسن طاعتهم لا يتكلمون إلا بما يأمرهم به ربهم، ولا يعملون عملاً حتى يأذن لهم."},{"id":"2511","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"28","aya_text":"يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ","aya_text_emlaey":"يعلم ما بين أيديهم وما خلفهم ولا يشفعون إلا لمن ارتضى وهم من خشيته مشفقون","aya_tafseer":"[28] وما من أعمال الملائكة عمل سابق أو لاحق إلا يعلمه الله سبحانه وتعالى، ويحصيه عليهم، ولا يتقدمون بالشفاعة إلا لمن ارتضى الله شفاعتهم له، وهم من خوف الله حذرون من مخالفة أمره ونهيه."},{"id":"2512","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"29","aya_text":"۞ وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ","aya_text_emlaey":"ومن يقل منهم إني إله من دونه فذلك نجزيه جهنم كذلك نجزي الظالمين","aya_tafseer":"[29] ومن يدَّع من الملائكة أنه إله مع الله -على سبيل الفرض- فجزاؤه جهنم، مثل ذلك الجزاء نجزي كل ظالم مشرك."},{"id":"2513","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"9","aya_no":"30","aya_text":"أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ","aya_text_emlaey":"أو لم ير الذين كفروا أن السموات والأرض كانتا رتقا ففتقناهما وجعلنا من الماء كل شيء حي أفلا يؤمنون","aya_tafseer":"[30] أَوَلَمْ يعلم هؤلاء الذين كفروا أن السموات والأرض كانتا ملتصقتين لا فاصل بينهما، فلا مطر من السماء ولا نبات من الأرض، ففصلناهما بقدرتنا، وأنزلنا المطر من السماء، وأخرجنا النبات من الأرض، وجعلنا من الماء كل شيء حي، أفلا يؤمن هؤلاء الجاحدون فيصدقوا بما يشاهدونه، ويخصُّوا الله بالعبادة؟"},{"id":"2514","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"11","aya_no":"31","aya_text":"وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ","aya_text_emlaey":"وجعلنا في الأرض رواسي أن تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون","aya_tafseer":"[31] وخلقنا في الأرض جبالاً تثبتها حتى لا تضطرب بأهلها، وجعلنا فيها طرقاً واسعة؛ رجاء اهتداء الخلق إلى معايشهم، وتوحيد خالقهم."},{"id":"2515","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"32","aya_text":"وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ","aya_text_emlaey":"وجعلنا السماء سقفا محفوظا وهم عن آياتها معرضون","aya_tafseer":"[32] وجعلنا السماء سقفاً للأرض لا يرفعها عماد، وهي محفوظة لا تسقط، ولا تخترقها الشياطين، والكفار عن الاعتبار بآيات السماء - الشمس والقمر والنجوم -، غافلون لاهون عن التفكير فيها."},{"id":"2516","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"33","aya_text":"وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ","aya_text_emlaey":"وهو الذي خلق الليل والنهار والشمس والقمر كل في فلك يسبحون","aya_tafseer":"[33] والله تعالى هو الذي خلق الليل؛ ليسكن الناس فيه، والنهار؛ ليطلبوا فيه المعايش، وخلق الشمس آية للنهار، والقمر آية للَّيل، ولكل منهما مدار يجري فيه ويَسْبَح لا يحيد عنه."},{"id":"2517","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"34","aya_text":"وَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ","aya_text_emlaey":"وما جعلنا لبشر من قبلك الخلد أفإن مت فهم الخالدون","aya_tafseer":"[34] وما جعلنا لبشر من قبلك -أيها الرسول- دوام البقاء في الدنيا، أفإن مت فهم يُؤمِّلون الخلود بعدك؟ لا يكون هذا. وفي هذه الآية دليل على أن الخضر عليه السلام قد مات؛ لأنه بشر."},{"id":"2518","jozz":"17","page":"324","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"15","aya_no":"35","aya_text":"كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ","aya_text_emlaey":"كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة وإلينا ترجعون","aya_tafseer":"[35] كل نفس ذائقة الموت لا محالة مهما عُمِّرت في الدنيا. وما وجودها في الحياة إلا ابتلاء بالتكاليف أمراً ونهياً، وبتقلب الأحوال خيراً وشرّاً، ثم المآل والمرجع بعد ذلك إلى الله -وحده- للحساب والجزاء."},{"id":"2519","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"3","aya_no":"36","aya_text":"وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ","aya_text_emlaey":"وإذا رآك الذين كفروا إن يتخذونك إلا هزوا أهذا الذي يذكر آلهتكم وهم بذكر الرحمن هم كافرون","aya_tafseer":"[36] وإذا رآك الكفار -أيها الرسول- أشاروا إليك ساخرين منك بقول بعضهم لبعض: أهذا الرجل الذي يَعيب آلهتكم؟ وجحدوا بالرحمن ونعمه، وبما أنزله من القرآن والهدى."},{"id":"2520","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"4","aya_no":"37","aya_text":"خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ","aya_text_emlaey":"خلق الإنسان من عجل سأريكم آياتي فلا تستعجلون","aya_tafseer":"[37] خُلق الإنسان عجولاً، يبادر الأشياء ويستعجل وقوعها. وقد استعجلتْ قريش العذاب واستبطأت وقوعه، فأنذرهم الله بأنه سيريهم ما يستعجلونه من العذاب، فلا يسألوا الله تعجيله وسرعته."},{"id":"2521","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"38","aya_text":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"ويقولون متى هذا الوعد إن كنتم صادقين","aya_tafseer":"[38] ويقول الكفار -مستعجلين العذاب مستهزئين-: متى حصول ما تَعِدُنا به يا محمد، إن كنت أنت ومَن اتبعك من الصادقين؟"},{"id":"2522","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"7","aya_no":"39","aya_text":"لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ","aya_text_emlaey":"لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون","aya_tafseer":"[39] لو يعلم هؤلاء الكفار ما يلاقونه عندما لا يستطيعون أن يدفعوا عن وجوههم وظهورهم النار، ولا يجدون لهم ناصراً ينصرهم؛ لَمَا أقاموا على كفرهم، ولَمَا استعجلوا عذابهم."},{"id":"2523","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"40","aya_text":"بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ","aya_text_emlaey":"بل تأتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون","aya_tafseer":"[40] ولسوف تأتيهم الساعة فجأة، فيتحيَّرون عند ذلك، ويخافون خوفاً عظيماً، ولا يستطيعون دَفْعَ العذاب عن أنفسهم، ولا يُمْهَلون لاستدراك توبة ولا اعتذار."},{"id":"2524","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"10","aya_no":"41","aya_text":"وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون","aya_tafseer":"[41] ولقد استهزئ برسل مِن قبلك أيها الرسول، فحلَّ بالذين كانوا يستهزئون بهم العذابَ الذي كان مَثار سخريتهم واستهزائهم."},{"id":"2525","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"11","aya_no":"42","aya_text":"قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ","aya_text_emlaey":"قل من يكلؤكم بالليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون","aya_tafseer":"[42] قل -أيها الرسول- لهؤلاء المستعجلين بالعذاب: لا أحد يحفظكم ويحرسكم في ليلكم أو نهاركم، في نومكم أو يقظتكم، مِن بأس الرحمن إذا نزل بكم. بل هم عن القرآن ومواعظ ربهم لاهون غافلون."},{"id":"2526","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"43","aya_text":"أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ","aya_text_emlaey":"أم لهم آلهة تمنعهم من دوننا لا يستطيعون نصر أنفسهم ولا هم منا يصحبون","aya_tafseer":"[43] أَ لَهُمْ آلهة تمنعهم من عذابنا؟ إنَّ آلهتهم لا يستطيعون أن ينصروا أنفسهم، فكيف ينصرون عابديهم؟ وهم منا لا يُجارون."},{"id":"2527","jozz":"17","page":"325","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"15","aya_no":"44","aya_text":"بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ","aya_text_emlaey":"بل متعنا هؤلاء وآباءهم حتى طال عليهم العمر أفلا يرون أنا نأتي الأرض ننقصها من أطرافها أفهم الغالبون","aya_tafseer":"[44] لقد اغترَّ الكفار وآباؤهم بالإمهال لِمَا رأوه من الأموال والبنين وطول الأعمار، فأقاموا على كفرهم لا يَبْرحونه، وظنوا أنهم لا يُعذَّبون وقد غَفَلوا عن سُنَّة ماضية، فالله ينقص الأرض من جوانبها بما ينزله بالمشركين مِن بأس في كل ناحية ومِن هزيمة، أيكون بوسع كفار «مكة» الخروجُ عن قدرة الله، أو الامتناع من الموت؟"},{"id":"2528","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"45","aya_text":"قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ","aya_text_emlaey":"قل إنما أنذركم بالوحي ولا يسمع الصم الدعاء إذا ما ينذرون","aya_tafseer":"[45] قل -أيها الرسول- لمن أُرسلتَ إليهم: ما أُخوِّفكم من العذاب إلَّا بوحي من الله، وهو القرآن، ولكن الكفار لا يسمعون ما يُلقى إليهم سماع تدبر إذا أُنذِروا، فلا ينتفعون به."},{"id":"2529","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"3","aya_no":"46","aya_text":"وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ","aya_text_emlaey":"ولئن مستهم نفحة من عذاب ربك ليقولن ياويلنا إنا كنا ظالمين","aya_tafseer":"[46] لو أصاب الكفارَ نصيب من عذاب الله لعلموا عاقبة تكذيبهم، وقابلوا ذلك بالدعاء على أنفسهم بالهلاك؛ بسبب ظلمهم لأنفسهم بعبادتهم غير الله."},{"id":"2530","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"5","aya_no":"47","aya_text":"وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ","aya_text_emlaey":"ونضع الموازين القسط ليوم القيامة فلا تظلم نفس شيئا وإن كان مثقال حبة من خردل أتينا بها وكفى بنا حاسبين","aya_tafseer":"[47] ويضع الله تعالى الميزان العادل للحساب في يوم القيامة، ولا يظلم هؤلاء ولا غيرهم شيئاً، وإن كان هذا العمل قَدْرَ ذرة مِن خير أو شر عُدَّت في حساب صاحبها. وكفى بالله محصياً أعمال عباده، ومجازياً لهم عليها."},{"id":"2531","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"48","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ","aya_text_emlaey":"ولقد آتينا موسى وهارون الفرقان وضياء وذكرا للمتقين","aya_tafseer":"[48] ولقد آتينا موسى وهارون حجة ونصراً على عدوهما، وكتاباً -وهو التوراة- فَرَقْنا به بين الحق والباطل، ونوراً يهتدي به المتقون"},{"id":"2532","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"49","aya_text":"ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ","aya_text_emlaey":"الذين يخشون ربهم بالغيب وهم من الساعة مشفقون","aya_tafseer":"[49] الذين يخافون عقاب ربهم، وهم من الساعة التي تقوم فيها القيامة خائفون وجلون."},{"id":"2533","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"9","aya_no":"50","aya_text":"وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ","aya_text_emlaey":"وهذا ذكر مبارك أنـزلناه أفأنتم له منكرون","aya_tafseer":"[50] وهذا القرآن الذي أنزله الله على رسوله محمد -صلى الله عليه وسلم- ذِكْرٌ لمن تذكَّر به، وعمل بأوامره واجتنب نواهيه، كثيرُ الخير، عظيمُ النفع، أفتنكرونه وهو في غاية الجلاء والظهور؟"},{"id":"2534","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"10","aya_no":"51","aya_text":"۞ وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ","aya_text_emlaey":"ولقد آتينا إبراهيم رشده من قبل وكنا به عالمين","aya_tafseer":"[51] ولقد آتينا إبراهيم هداه، الذي دعا الناس إليه من قبل موسى وهارون، وكنَّا عالمين أنه أهل لذلك."},{"id":"2535","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"11","aya_no":"52","aya_text":"إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ","aya_text_emlaey":"إذ قال لأبيه وقومه ما هذه التماثيل التي أنتم لها عاكفون","aya_tafseer":"[52] حين قال لأبيه وقومه: ما هذه الأصنام التي صنعتموها، ثم أقمتم على عبادتها ملازمين لها؟"},{"id":"2536","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"11","aya_no":"53","aya_text":"قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ","aya_text_emlaey":"قالوا وجدنا آباءنا لها عابدين","aya_tafseer":"[53] قالوا: وجدنا آباءنا عابدين لها، ونحن نعبدها اقتداء بهم."},{"id":"2537","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"54","aya_text":"قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ","aya_text_emlaey":"قال لقد كنتم أنتم وآباؤكم في ضلال مبين","aya_tafseer":"[54] قال لهم إبراهيم: لقد كنتم أنتم وآباؤكم في عبادتكم لهذه الأصنام في بُعْدٍ واضح بيِّن عن الحق."},{"id":"2538","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"55","aya_text":"قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ","aya_text_emlaey":"قالوا أجئتنا بالحق أم أنت من اللاعبين","aya_tafseer":"[55] قالوا: أهذا القول الذي جئتنا به حق وَجِدٌّ، أم كلامك لنا كلام لاعبٍ مستهزئ لا يدري ما يقول؟"},{"id":"2539","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"56","aya_text":"قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ","aya_text_emlaey":"قال بل ربكم رب السموات والأرض الذي فطرهن وأنا على ذلكم من الشاهدين","aya_tafseer":"[56] قال لهم إبراهيم عليه الصلاة والسلام: بل ربكم الذي أدعوكم إلى عبادته هو رب السموات والأرض الذي خلقهنَّ، وأنا من الشاهدين على ذلك."},{"id":"2540","jozz":"17","page":"326","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"15","line_end":"15","aya_no":"57","aya_text":"وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ","aya_text_emlaey":"وتالله لأكيدن أصنامكم بعد أن تولوا مدبرين","aya_tafseer":"[57] وتالله لأمكرنَّ بأصنامكم ولأكسِّرنَّها بعد أن تتولَّوا عنها ذاهبين."},{"id":"2541","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"1","aya_no":"58","aya_text":"فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ","aya_text_emlaey":"فجعلهم جذاذا إلا كبيرا لهم لعلهم إليه يرجعون","aya_tafseer":"[58] فحطَّم إبراهيم الأصنام وجعلها قطعاً صغيرة، وترك كبيرها؛ كي يرجع القوم إليه ويسألوه، فيتبين عجزهم وضلالهم، وتقوم الحجة عليهم."},{"id":"2542","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"2","aya_no":"59","aya_text":"قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"قالوا من فعل هذا بآلهتنا إنه لمن الظالمين","aya_tafseer":"[59] ورجع القوم، ورأوا أصنامهم محطمة مهانة، فسأل بعضهم بعضاً: مَن فعل هذا بآلهتنا؟ إنه لظالم في اجترائه على الآلهة المستحقة للتعظيم والتوقير."},{"id":"2543","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"3","aya_no":"60","aya_text":"قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ","aya_text_emlaey":"قالوا سمعنا فتى يذكرهم يقال له إبراهيم","aya_tafseer":"[60] قال مَن سمع إبراهيمَ يحلف بأنه سيكيد أصنامهم: سمعنا فتى يذكر الأصنام بسوء يقال له إبراهيم."},{"id":"2544","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"4","aya_no":"61","aya_text":"قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ","aya_text_emlaey":"قالوا فأتوا به على أعين الناس لعلهم يشهدون","aya_tafseer":"[61] قال رؤساؤهم: فَأْتوا بإبراهيم على مرأى من الناس؛ كي يشهدوا على اعترافه بما قال؛ ليكون ذلك حجة عليه."},{"id":"2545","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"62","aya_text":"قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ","aya_text_emlaey":"قالوا أأنت فعلت هذا بآلهتنا ياإبراهيم","aya_tafseer":"[62] وجيء بإبراهيم وسألوه منكرين: أأنت الذي كسَّرْتَ آلهتنا؟ يعنون أصنامهم."},{"id":"2546","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"6","aya_no":"63","aya_text":"قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ","aya_text_emlaey":"قال بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون","aya_tafseer":"[63] وتمَّ لإبراهيم ما أراد من إظهار سفههم على مرأى منهم. فقال محتجّاً عليهم معرِّضاً بغباوتهم: بل الذي كسَّرها هذا الصنم الكبير، فاسألوا آلهتكم المزعومة عن ذلك، إن كانت تتكلم أو تردُّ جواباً."},{"id":"2547","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"64","aya_text":"فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"فرجعوا إلى أنفسهم فقالوا إنكم أنتم الظالمون","aya_tafseer":"[64] فأُسقِط في أيديهم، وبدا لهم ضلالهم؛ كيف يعبدونها، وهي عاجزة عن أن تدفع عن نفسها شيئاً أو أن تجيب سائلها؟ وأقرُّوا على أنفسهم بالظلم والشرك."},{"id":"2548","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"65","aya_text":"ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ","aya_text_emlaey":"ثم نكسوا على رءوسهم لقد علمت ما هؤلاء ينطقون","aya_tafseer":"[65] وسُرعان ما عاد إليهم عنادهم بعد إفحامهم، فانقلبوا إلى الباطل، واحتجُّوا على إبراهيم بما هو حجة له عليهم، فقالوا: كيف نسألها، وقد علمتَ أنها لا تنطق؟"},{"id":"2549","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"10","aya_no":"66","aya_text":"قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ","aya_text_emlaey":"قال أفتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم","aya_tafseer":"[66] قال إبراهيم محقِّراً لشأن الأصنام: كيف تعبدون أصناماً لا تنفع إذا عُبدت، ولا تضرُّ إذا تُركت؟"},{"id":"2550","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"11","aya_no":"67","aya_text":"أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"أف لكم ولما تعبدون من دون الله أفلا تعقلون","aya_tafseer":"[67] قبحاً لكم ولآلهتكم التي تعبدونها من دون الله تعالى، أفلا تعقلون فتدركون سوء ما أنتم عليه؟"},{"id":"2551","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"68","aya_text":"قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ","aya_text_emlaey":"قالوا حرقوه وانصروا آلهتكم إن كنتم فاعلين","aya_tafseer":"[68] لما بطلت حجتهم وظهر الحق عدلوا إلى استعمال سلطانهم، وقالوا: حَرِّقوا إبراهيم بالنار؛ غضباً لآلهتكم إن كنتم ناصرين لها."},{"id":"2552","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"12","aya_no":"69","aya_text":"قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ","aya_text_emlaey":"قلنا يانار كوني بردا وسلاما على إبراهيم","aya_tafseer":"[69] فأشْعَلوا ناراً عظيمة وألقوه فيها، فانتصر الله لرسوله وقال للنار: كوني برداً وسلاماً على إبراهيم، فلم يَنَلْه فيها أذى، ولم يصبه مكروه."},{"id":"2553","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"13","aya_no":"70","aya_text":"وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ","aya_text_emlaey":"وأرادوا به كيدا فجعلناهم الأخسرين","aya_tafseer":"[70] وأراد القوم بإبراهيم الهلاك فأبطل الله كيدهم، وجعلهم المغلوبين الأسفلين."},{"id":"2554","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"71","aya_text":"وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ","aya_text_emlaey":"ونجيناه ولوطا إلى الأرض التي باركنا فيها للعالمين","aya_tafseer":"[71] ونجينا إبراهيم ولوطاً الذي آمن به من «العراق»، وأخرجناهما إلى أرض «الشام» التي باركنا فيها بكثرة الخيرات، وفيها أكثر الأنبياء عليهم الصلاة والسلام."},{"id":"2555","jozz":"17","page":"327","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"15","aya_no":"72","aya_text":"وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ","aya_text_emlaey":"ووهبنا له إسحاق ويعقوب نافلة وكلا جعلنا صالحين","aya_tafseer":"[72] وأنعم الله على إبراهيم، فوهب له ابنه إسحاق حين دعاه، ووهب له من إسحاق يعقوب زيادة على ذلك، وكلٌّ من إبراهيم وإسحاق ويعقوب جعله الله صالحاً مطيعاً له."},{"id":"2556","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"3","aya_no":"73","aya_text":"وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ","aya_text_emlaey":"وجعلناهم أئمة يهدون بأمرنا وأوحينا إليهم فعل الخيرات وإقام الصلاة وإيتاء الزكاة وكانوا لنا عابدين","aya_tafseer":"[73] وجعلنا إبراهيم وإسحاق ويعقوب قدوة للناس يدعونهم إلى عبادة الله وطاعته بإذنه تعالى، وأوحينا إليهم فِعْلَ الخيرات من العمل بشرائع الأنبياء، وإقام الصلاة على وجهها، وإيتاء الزكاة، فامتثلوا لذلك، وكانوا منقادين مطيعين لله وحده دون سواه."},{"id":"2557","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"3","line_end":"5","aya_no":"74","aya_text":"وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ","aya_text_emlaey":"ولوطا آتيناه حكما وعلما ونجيناه من القرية التي كانت تعمل الخبائث إنهم كانوا قوم سوء فاسقين","aya_tafseer":"[74] وآتينا لوطاً النبوة وفَصْل القضاء بين الخصوم وعلماً بأمر الله ودينه، ونجيناه مِن قريته «سَدُوم» التي كان يعمل أهلها الخبائث. إنهم كانوا بسبب الخبائث والمنكرات التي يأتونها أهل سوء وقُبْح، خارجين عن طاعة الله."},{"id":"2558","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"5","aya_no":"75","aya_text":"وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"وأدخلناه في رحمتنا إنه من الصالحين","aya_tafseer":"[75] وأتمَّ الله عليه النعمة فأدخله في رحمته بإنجائه ممَّا حلَّ بقومه؛ لأنه كان من الذين يعملون بطاعة الله."},{"id":"2559","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"76","aya_text":"وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ","aya_text_emlaey":"ونوحا إذ نادى من قبل فاستجبنا له فنجيناه وأهله من الكرب العظيم","aya_tafseer":"[76] واذكر -أيها الرسول- نوحاً حين نادى ربه مِن قبلك ومِن قبل إبراهيم ولوط، فاستجبنا له دعاءه، فنجيناه وأهله المؤمنين به من الغم الشديد."},{"id":"2560","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"9","aya_no":"77","aya_text":"وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ","aya_text_emlaey":"ونصرناه من القوم الذين كذبوا بآياتنا إنهم كانوا قوم سوء فأغرقناهم أجمعين","aya_tafseer":"[77] ونصرناه مِن كيد القوم الذين كذَّبوا بآياتنا الدالة على صدقه، إنهم كانوا أهل قُبْح، فأغرقناهم بالطوفان أجمعين."},{"id":"2561","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"10","aya_no":"78","aya_text":"وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ","aya_text_emlaey":"وداود وسليمان إذ يحكمان في الحرث إذ نفشت فيه غنم القوم وكنا لحكمهم شاهدين","aya_tafseer":"[78] واذكر -أيها الرسول- نبي الله داود وابنه سليمان، إذ يحكمان في قضية عَرَضَها خصمان، عَدَت غنم أحدهما على زرع الآخر، وانتشرت فيه ليلاً، فأتلفت الزرع، فحكم داود بأن تكون الغنم لصاحب الزرع مُلْكاً بما أتلفته، فقيمتهما سواء، وكنَّا لحكمهم شاهدين لم يَغِبْ عنا."},{"id":"2562","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"79","aya_text":"فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ","aya_text_emlaey":"ففهمناها سليمان وكلا آتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فاعلين","aya_tafseer":"[79] فَفَهَّمنا سليمان مراعاة مصلحة الطرفين مع العدل، فحكم على صاحب الغنم بإصلاح الزرع التالف في فترة يستفيد فيها صاحب الزرع بمنافع الغنم من لبن وصوف ونحوهما، ثم تعود الغنم إلى صاحبها والزرع إلى صاحبه؛ لمساواة قيمة ما تلف من الزرع لمنفعة الغنم، وكلًّا من داود وسليمان أعطيناه حكماً وعلماً، ومننَّا على داود بتطويع الجبال تسبِّح معه إذا سبَّح، وكذلك الطير تسبِّح، وكنا فاعلين ذلك."},{"id":"2563","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"80","aya_text":"وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ","aya_text_emlaey":"وعلمناه صنعة لبوس لكم لتحصنكم من بأسكم فهل أنتم شاكرون","aya_tafseer":"[80] واختصَّ الله داود عليه السلام بأن علَّمه صناعة الدروع يعملها حِلَقاً متشابكة، تسهِّل حركة الجسم؛ لتحمي المحاربين مِن وَقْع السلاح فيهم، فهل أنتم شاكرون نعمة الله عليكم حيث أجراها على يد عبده داود؟"},{"id":"2564","jozz":"17","page":"328","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"15","aya_no":"81","aya_text":"وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ","aya_text_emlaey":"ولسليمان الريح عاصفة تجري بأمره إلى الأرض التي باركنا فيها وكنا بكل شيء عالمين","aya_tafseer":"[81] وسخَّرنا لسليمان الريح شديدة الهبوب تحمله ومَن معه، تجري بأمره إلى أرض «بيت المقدس» ﺑ«الشام» التي باركنا فيها بالخيرات الكثيرة، وقد أحاط علمنا بجميع الأشياء."},{"id":"2565","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"82","aya_text":"وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ","aya_text_emlaey":"ومن الشياطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حافظين","aya_tafseer":"[82] وسخَّرنا لسليمان من الشياطين شياطين يستخدمهم فيما يَعْجِز عنه غيرهم، فكانوا يغوصون في البحر يستخرجون له اللآلئ والجواهر، وكانوا يعملون كذلك في صناعة ما يريده منهم، لا يقدرون على الامتناع مما يريده منهم، حفظهم الله له بقوته وعزه سبحانه وتعالى."},{"id":"2566","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"3","aya_no":"83","aya_text":"۞ وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ","aya_text_emlaey":"وأيوب إذ نادى ربه أني مسني الضر وأنت أرحم الراحمين","aya_tafseer":"[83] واذكر -أيها الرسول- عبدنا أيوب، إذ ابتليناه بضر وسقم عظيم في جسده، وفقد أهله وماله وولده، فصبر واحتسب، ونادى ربه عز وجل أني قد أصابني الضر، وأنت أرحم الراحمين، فاكشفه عني."},{"id":"2567","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"5","aya_no":"84","aya_text":"فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ","aya_text_emlaey":"فاستجبنا له فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين","aya_tafseer":"[84] فاستجبنا له دعاءه، ورفعنا عنه البلاء، ورددنا عليه ما فقده من أهل وولد ومال مضاعفاً، فَعَلْنا به ذلك رحمة منَّا، وليكون قدوة لكل صابر على البلاء، راجٍ رحمة ربه، عابد له."},{"id":"2568","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"6","aya_no":"85","aya_text":"وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"وإسماعيل وإدريس وذا الكفل كل من الصابرين","aya_tafseer":"[85] واذكر إسماعيل وإدريس وذا الكفل، كل هؤلاء من الصابرين على طاعة الله سبحانه وتعالى، وعن معاصيه، وعلى أقداره، فاستحقوا الذكر بالثناء الجميل."},{"id":"2569","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"7","aya_no":"86","aya_text":"وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"وأدخلناهم في رحمتنا إنهم من الصالحين","aya_tafseer":"[86] وأدخلناهم في رحمتنا، إنهم ممن صلح باطنه وظاهره، فأطاع الله وعمل بما أمره به."},{"id":"2570","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"10","aya_no":"87","aya_text":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وذا النون إذ ذهب مغاضبا فظن أن لن نقدر عليه فنادى في الظلمات أن لا إله إلا أنت سبحانك إني كنت من الظالمين","aya_tafseer":"[87] واذكر قصة صاحب الحوت، وهو يونس بن مَتَّى عليه السلام، أرسله الله إلى قومه فدعاهم فلم يؤمنوا، فتوعَّدهم بالعذاب فلم ينيبوا، ولم يصبر عليهم كما أمره الله، وخرج مِن بينهم غاضباً عليهم، ضائقاً صدره بعصيانهم، وظن أن الله لن يضيِّق عليه ويؤاخذه بهذه المخالفة، فابتلاه الله بشدة الضيق والحبس، والتقمه الحوت في البحر، فنادى ربه في ظلمات الليل والبحر وبطن الحوت -تائباً معترفاً بظلمه؛ لتركه الصبر على قومه- قائلاً: لا إله إلا أنت سبحانك، إني كنت من الظالمين."},{"id":"2571","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"10","line_end":"11","aya_no":"88","aya_text":"فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين","aya_tafseer":"[88] فاستجبنا له دعاءه، وخلَّصناه مِن غمِّ هذه الشدة، وكذلك ننجي المصدِّقين العاملين بشرعنا."},{"id":"2572","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"89","aya_text":"وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ","aya_text_emlaey":"وزكريا إذ نادى ربه رب لا تذرني فردا وأنت خير الوارثين","aya_tafseer":"[89] واذكر -أيها الرسول- قصة عبد الله زكريا حين دعا ربه أن يرزقه الذرية لما كَبِرت سنُّه قائلاً: رب لا تتركني وحيداً لا عقب لي، هب لي وارثاً يقوم بأمر الدين في الناس من بعدي، وأنت خير الباقين وخير مَن خلفني بخير."},{"id":"2573","jozz":"17","page":"329","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"15","aya_no":"90","aya_text":"فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ","aya_text_emlaey":"فاستجبنا له ووهبنا له يحيى وأصلحنا له زوجه إنهم كانوا يسارعون في الخيرات ويدعوننا رغبا ورهبا وكانوا لنا خاشعين","aya_tafseer":"[90] فاستجبنا له دعاءه ووهبنا له على الكبر ابنه يحيى، وجعلنا زوجته صالحة في أخلاقها وصالحة للحمل والولادة بعد أن كانت عاقراً، إنهم كانوا يبادرون إلى كل خير، ويدعوننا راغبين فيما عندنا، خائفين من عقوبتنا، وكانوا لنا خاضعين متواضعين."},{"id":"2574","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"91","aya_text":"وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ","aya_text_emlaey":"والتي أحصنت فرجها فنفخنا فيها من روحنا وجعلناها وابنها آية للعالمين","aya_tafseer":"[91] واذكر -أيها الرسول- قصة مريم بنت عمران التي حفظت فرجها من الحرام، ولم تأتِ فاحشة في حياتها، فأرسل الله إليها جبريل عليه السلام، فنفخ في جيب قميصها، فوصلت النفخة إلى رحمها، فخلق الله بذلك النفخ المسيح عيسى عليه السلام، فحملت به من غير زوج، فكانت هي وابنها بذلك علامة على قدرة الله، وعبرة للخلق إلى قيام الساعة."},{"id":"2575","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"3","aya_no":"92","aya_text":"إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ","aya_text_emlaey":"إن هذه أمتكم أمة واحدة وأنا ربكم فاعبدون","aya_tafseer":"[92] هؤلاء الأنبياء جميعاً دينهم واحد، الإسلام، وهو الاستسلام لله بالطاعة وإفرادُه بالعبادة، والله سبحانه وتعالى رب الخلق فاعبدوه -أيها الناس- وحده لا شريك له."},{"id":"2576","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"4","aya_no":"93","aya_text":"وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ","aya_text_emlaey":"وتقطعوا أمرهم بينهم كل إلينا راجعون","aya_tafseer":"[93] لكن الناس اختلفوا على رسلهم، وتفرَّق كثير من أتباعهم في الدين شيعاً وأحزاباً، فعبدوا المخلوقين والأهواء، وكلهم راجعون إلينا ومحاسبون على ما فعلوا."},{"id":"2577","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"5","line_end":"6","aya_no":"94","aya_text":"فَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ","aya_text_emlaey":"فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه وإنا له كاتبون","aya_tafseer":"[94] فمن التزم الإيمان بالله ورسله، وعمل ما يستطيع من صالح الأعمال طاعةً لله وعبادة له فلا يضيع الله عمله ولا يبطله، بل يضاعفه كلَّه أضعافاً كثيرة، وسيجد ما عمله في كتابه يوم يُبْعث بعد موته."},{"id":"2578","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"95","aya_text":"وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ","aya_text_emlaey":"وحرام على قرية أهلكناها أنهم لا يرجعون","aya_tafseer":"[95] وممتنع على أهل القرى التي أهلكناها بسبب كفرهم وظلمهم، رجوعهم إلى الدنيا قبل يوم القيامة؛ ليستدركوا ما فرطوا فيه."},{"id":"2579","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"7","line_end":"8","aya_no":"96","aya_text":"حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ","aya_text_emlaey":"حتى إذا فتحت يأجوج ومأجوج وهم من كل حدب ينسلون","aya_tafseer":"[96] فإذا فُتِح سد يأجوج ومأجوج، وانطلقوا من مرتفعات الأرض وانتشروا في جنباتها مسرعين،"},{"id":"2580","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"11","aya_no":"97","aya_text":"وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ","aya_text_emlaey":"واقترب الوعد الحق فإذا هي شاخصة أبصار الذين كفروا ياويلنا قد كنا في غفلة من هذا بل كنا ظالمين","aya_tafseer":"[97] دنا يوم القيامة وبدَتْ أهواله فإذا أبصار الكفار مِن شدة الفزع مفتوحة لا تكاد تَطْرِف، يدعون على أنفسهم بالويل في حسرة: يا ويلنا قد كنا لاهين غافلين عن هذا اليوم وعن الإعداد له، وكنا بذلك ظالمين."},{"id":"2581","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"98","aya_text":"إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ","aya_text_emlaey":"إنكم وما تعبدون من دون الله حصب جهنم أنتم لها واردون","aya_tafseer":"[98] إنكم -أيها الكفار- وما كنتم تعبدون من دون الله من الأصنام ومَن رضي بعبادتكم إياه من الجن والإنس، وقود جهنم وحطبها، أنتم وهم فيها داخلون."},{"id":"2582","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"99","aya_text":"لَوۡ كَانَ هَٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"لو كان هؤلاء آلهة ما وردوها وكل فيها خالدون","aya_tafseer":"[99] لو كان هؤلاء الذين عبدتموهم من دون الله تعالى آلهة تستحق العبادة ما دخلوا نار جهنم معكم أيها المشركون، إنَّ كُلّاً من العابدين والمعبودين خالدون في نار جهنم."},{"id":"2583","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"14","aya_no":"100","aya_text":"لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ","aya_text_emlaey":"لهم فيها زفير وهم فيها لا يسمعون","aya_tafseer":"[100] لهؤلاء المعذبين في النار آلام ينبئ عنها زفيرهم الذي تندفع فيه أنفاسهم من صدورهم بشدَّة، وهم في النار لا يسمعون؛ من هول عذابهم."},{"id":"2584","jozz":"17","page":"330","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"15","aya_no":"101","aya_text":"إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَٰٓئِكَ عَنۡهَا مُبۡعَدُونَ","aya_text_emlaey":"إن الذين سبقت لهم منا الحسنى أولئك عنها مبعدون","aya_tafseer":"[101] إن الذين سبقت لهم منا سابقة السعادة الحسنة في علمنا بكونهم من أهل الجنة، أولئك عن النار مبعدون، فلا يدخلونها ولا يكونون قريباً منها."},{"id":"2585","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"1","line_end":"2","aya_no":"102","aya_text":"لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ","aya_text_emlaey":"لا يسمعون حسيسها وهم في ما اشتهت أنفسهم خالدون","aya_tafseer":"[102] لا يسمعون صوت لهيبها واحتراق الأجساد فيها، فقد سكنوا منازلهم في الجنة، وأصبحوا فيما تشتهيه نفوسهم من نعيمها ولذاتها مقيمين إقامةً دائمة."},{"id":"2586","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"2","line_end":"3","aya_no":"103","aya_text":"لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ","aya_text_emlaey":"لا يحزنهم الفزع الأكبر وتتلقاهم الملائكة هذا يومكم الذي كنتم توعدون","aya_tafseer":"[103] لا يخيفهم الهول العظيم يوم القيامة، بل تبشرهم الملائكة: هذا يومكم الذي وُعِدتُم فيه الكرامة من الله وجزيل الثواب."},{"id":"2587","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"4","line_end":"6","aya_no":"104","aya_text":"يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ","aya_text_emlaey":"يوم نطوي السماء كطي السجل للكتب كما بدأنا أول خلق نعيده وعدا علينا إنا كنا فاعلين","aya_tafseer":"[104] يوم نطوي السماء كما تُطْوى الصحيفة على ما كُتب فيها، ونبعث فيه الخلق على هيئة خَلْقنا لهم أول مرة، كما ولدتهم أمهاتهم، ذلك وعد الله الذي لا يُخْلَف، وَعَدْنا بذلك وعداً حقّاً علينا، إنا كنا فاعلين دائماً ما نَعِدُ به."},{"id":"2588","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"6","line_end":"7","aya_no":"105","aya_text":"وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ","aya_text_emlaey":"ولقد كتبنا في الزبور من بعد الذكر أن الأرض يرثها عبادي الصالحون","aya_tafseer":"[105] ولقد كتبنا في الكتب المنزلة من بعد ما كُتِب في اللوح المحفوظ: أن الأرض يرثها عباد الله الصالحون الذين قاموا بما أُمروا به، واجتنبوا ما نُهوا عنه، وهم أمة محمد -صلى الله عليه وسلم-."},{"id":"2589","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"8","aya_no":"106","aya_text":"إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ","aya_text_emlaey":"إن في هذا لبلاغا لقوم عابدين","aya_tafseer":"[106] إن في هذا المتلوِّ من الموعظة لَعبرة كافية لقوم عابدين الله بما شرعه لهم ورضيه منهم."},{"id":"2590","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"8","line_end":"9","aya_no":"107","aya_text":"وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ","aya_text_emlaey":"وما أرسلناك إلا رحمة للعالمين","aya_tafseer":"[107] وما أرسلناك -أيها الرسول- إلا رحمة لجميع الناس، فمن آمن بك سَعِد ونجا، ومن لم يؤمن خاب وخسر."},{"id":"2591","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"9","line_end":"10","aya_no":"108","aya_text":"قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ","aya_text_emlaey":"قل إنما يوحى إلي أنما إلهكم إله واحد فهل أنتم مسلمون","aya_tafseer":"[108] قل: إن الذي أُوحي إليَّ وبُعِثت به: أن إلهكم الذي يستحق العبادة وحده هو الله، فأسلِموا له، وانقادوا لعبادته."},{"id":"2592","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"11","line_end":"12","aya_no":"109","aya_text":"فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ","aya_text_emlaey":"فإن تولوا فقل آذنتكم على سواء وإن أدري أقريب أم بعيد ما توعدون","aya_tafseer":"[109] فإن أعرض هؤلاء عن الإسلام فقل لهم: أبلغكم جميعاً ما أوحاه الله تعالى إليَّ، فأنا وأنتم مستوون في العلم لَمَّا أنذرتكم وحذرتكم، ولستُ أعلم -بعد ذلك- متى يحلُّ بكم ما وُعِدْتُم به من العذاب."},{"id":"2593","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"12","line_end":"13","aya_no":"110","aya_text":"إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ","aya_text_emlaey":"إنه يعلم الجهر من القول ويعلم ما تكتمون","aya_tafseer":"[110] إن الله يعلم ما تجهرون به من أقوالكم، وما تكتمونه في سرائركم، وسيحاسبكم عليه."},{"id":"2594","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"13","line_end":"14","aya_no":"111","aya_text":"وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ","aya_text_emlaey":"وإن أدري لعله فتنة لكم ومتاع إلى حين","aya_tafseer":"[111] ولست أدري لعلَّ تأخير العذاب الذي استعجلتموه استدراج لكم وابتلاء، وأن تتمتعوا في الدنيا إلى حين؛ لتزدادوا كفراً، ثم يكون أعظم لعقوبتكم."},{"id":"2595","jozz":"17","page":"331","sura_no":"21","sura_name_en":"Al-Anbiyā’","sura_name_ar":"الأنبيَاء ","line_start":"14","line_end":"15","aya_no":"112","aya_text":"قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ","aya_text_emlaey":"قال رب احكم ‎ بالحق وربنا الرحمن المستعان على ما تصفون","aya_tafseer":"[112] قال النبي -صلى الله عليه وسلم-: ربِّ افصل بيننا وبين قومنا المكذبين بالقضاء الحق. ونسأل ربَّنا الرحمن، ونستعين به على ما تَصِفونه -أيها الكفار- من الشرك والتكذيب والافتراء عليه، وما تتوعدوننا به من الظهور والغلبة."}]
